CREATE TABLE IF NOT EXISTS schema_migrations(version INTEGER PRIMARY KEY,name TEXT NOT NULL,checksum TEXT NOT NULL,applied_at TEXT NOT NULL);
CREATE TABLE excerpt_folders(id INTEGER PRIMARY KEY AUTOINCREMENT,item_id INTEGER NOT NULL,parent_id INTEGER,name TEXT NOT NULL,sort INTEGER NOT NULL DEFAULT 0);
CREATE UNIQUE INDEX folder_sibling ON excerpt_folders(item_id,COALESCE(parent_id,0),name);
CREATE TABLE excerpt_folder_links(folder_id INTEGER NOT NULL,excerpt_id INTEGER NOT NULL,PRIMARY KEY(folder_id,excerpt_id));
CREATE TABLE themes(id INTEGER PRIMARY KEY AUTOINCREMENT,parent_id INTEGER,name TEXT NOT NULL,sort INTEGER NOT NULL DEFAULT 0);
CREATE UNIQUE INDEX theme_sibling ON themes(COALESCE(parent_id,0),name);
CREATE TABLE theme_links(theme_id INTEGER NOT NULL,content_type TEXT NOT NULL CHECK(content_type IN ('excerpt','compilation','note','idea','historyPaper')),content_id INTEGER NOT NULL,PRIMARY KEY(theme_id,content_type,content_id));
CREATE INDEX theme_content ON theme_links(content_type,content_id);
CREATE TABLE writing_documents(id INTEGER PRIMARY KEY AUTOINCREMENT,kind TEXT NOT NULL,entity_id INTEGER NOT NULL,schema_version INTEGER NOT NULL DEFAULT 1,revision INTEGER NOT NULL DEFAULT 1,content_json TEXT NOT NULL,plain_text TEXT NOT NULL DEFAULT '',legacy_mode INTEGER NOT NULL DEFAULT 1,updated_at TEXT NOT NULL,UNIQUE(kind,entity_id));
CREATE TABLE writing_citations(uuid TEXT PRIMARY KEY,document_id INTEGER NOT NULL,payload_json TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1);
CREATE INDEX citation_document ON writing_citations(document_id);
CREATE TABLE writing_resources(uuid TEXT PRIMARY KEY,rel_path TEXT NOT NULL,mime TEXT NOT NULL,size INTEGER NOT NULL,width INTEGER NOT NULL,height INTEGER NOT NULL,sha256 TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE document_resource_links(document_id INTEGER NOT NULL,resource_id TEXT NOT NULL,PRIMARY KEY(document_id,resource_id));
CREATE TABLE pdf_annotations(uuid TEXT PRIMARY KEY,attachment_id INTEGER NOT NULL,kind TEXT NOT NULL,group_id TEXT,revision INTEGER NOT NULL DEFAULT 1,geometry_json TEXT NOT NULL,selected_text TEXT NOT NULL DEFAULT '',note TEXT NOT NULL DEFAULT '',color TEXT NOT NULL DEFAULT '#ffdb58',created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE INDEX annotation_attachment ON pdf_annotations(attachment_id);
CREATE TABLE annotation_excerpt_links(annotation_id TEXT NOT NULL,excerpt_id INTEGER NOT NULL,PRIMARY KEY(annotation_id,excerpt_id));
CREATE TABLE writing_drafts(document_id INTEGER NOT NULL,client_id TEXT NOT NULL,base_revision INTEGER NOT NULL,draft_json TEXT NOT NULL,saved_at TEXT NOT NULL,PRIMARY KEY(document_id,client_id));
CREATE TABLE writing_mutations(document_id INTEGER NOT NULL,mutation_id TEXT NOT NULL,result_json TEXT NOT NULL,created_at TEXT NOT NULL,PRIMARY KEY(document_id,mutation_id));
CREATE TABLE idea_conversions(idea_id INTEGER PRIMARY KEY,compilation_id INTEGER NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE conversion_requests(request_id TEXT PRIMARY KEY,result_json TEXT NOT NULL);
CREATE TABLE legacy_content(kind TEXT NOT NULL,entity_id INTEGER NOT NULL,payload_json TEXT NOT NULL,PRIMARY KEY(kind,entity_id));
CREATE TRIGGER excerpt_revision AFTER UPDATE OF text,locator,comment,locator_json,source_json ON excerpts WHEN NEW.text<>OLD.text OR NEW.locator<>OLD.locator OR NEW.comment<>OLD.comment OR NEW.locator_json<>OLD.locator_json OR NEW.source_json<>OLD.source_json BEGIN UPDATE excerpts SET revision=OLD.revision+1,updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id=NEW.id; END;
CREATE TRIGGER item_revision AFTER UPDATE OF title,subtitle,fields ON items WHEN NEW.title<>OLD.title OR NEW.subtitle<>OLD.subtitle OR NEW.fields<>OLD.fields BEGIN UPDATE items SET source_revision=OLD.source_revision+1 WHERE id=NEW.id; END;
CREATE TRIGGER excerpt_cleanup AFTER DELETE ON excerpts BEGIN DELETE FROM excerpt_folder_links WHERE excerpt_id=OLD.id; DELETE FROM theme_links WHERE content_type='excerpt' AND content_id=OLD.id; DELETE FROM annotation_excerpt_links WHERE excerpt_id=OLD.id; END;
CREATE TRIGGER item_folder_cleanup AFTER DELETE ON items BEGIN DELETE FROM excerpt_folder_links WHERE folder_id IN (SELECT id FROM excerpt_folders WHERE item_id=OLD.id); DELETE FROM excerpt_folders WHERE item_id=OLD.id; END;
CREATE TRIGGER note_v2_cleanup AFTER DELETE ON notes BEGIN DELETE FROM theme_links WHERE content_type='note' AND content_id=OLD.id; DELETE FROM writing_documents WHERE kind='note' AND entity_id=OLD.id; END;
CREATE TRIGGER idea_v2_cleanup AFTER DELETE ON ideas BEGIN DELETE FROM theme_links WHERE content_type='idea' AND content_id=OLD.id; DELETE FROM writing_documents WHERE kind='idea' AND entity_id=OLD.id; DELETE FROM idea_conversions WHERE idea_id=OLD.id; END;
CREATE TRIGGER comp_v2_cleanup AFTER DELETE ON compilations BEGIN DELETE FROM theme_links WHERE content_type='compilation' AND content_id=OLD.id; DELETE FROM writing_documents WHERE kind='compilation' AND entity_id=OLD.id; DELETE FROM idea_conversions WHERE compilation_id=OLD.id; END;
CREATE TRIGGER document_v2_cleanup AFTER DELETE ON writing_documents BEGIN DELETE FROM writing_citations WHERE document_id=OLD.id; DELETE FROM document_resource_links WHERE document_id=OLD.id; DELETE FROM writing_drafts WHERE document_id=OLD.id; DELETE FROM writing_mutations WHERE document_id=OLD.id; END;

CREATE TABLE pdf_annotation_drafts(attachment_id INTEGER NOT NULL,client_id TEXT NOT NULL,draft_json TEXT NOT NULL,saved_at TEXT NOT NULL,PRIMARY KEY(attachment_id,client_id));
